const text = ($json.body?.request ?? $json.request ?? '').toString();
if (!text) throw new Error('Missing request text in body.request or request');

const attendeeMatches = [...text.matchAll(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi)].map(m => m[0].toLowerCase());
const attendees = [...new Set(attendeeMatches)];

const durationMatch = text.match(/(\d+)\s*(?:hr|hour|hours|h)\b/i) || text.match(/(\d+)\s*(?:min|minute|minutes|m)\b/i);
let durationMinutes = 60;
if (durationMatch) {
  const val = parseInt(durationMatch[1], 10);
  durationMinutes = /hr|hour|hours|h/i.test(durationMatch[0]) ? val * 60 : val;
}

let avoidBeforeHour = 9;
const avoidMatch = text.match(/avoid\s+before\s+(\d{1,2})(?::(\d{2}))?\s*(am|pm)?/i);
if (avoidMatch) {
  let h = parseInt(avoidMatch[1], 10);
  const ampm = (avoidMatch[3] || '').toLowerCase();
  if (ampm === 'pm' && h < 12) h += 12;
  if (ampm === 'am' && h === 12) h = 0;
  avoidBeforeHour = h;
}

const topicMatch = text.match(/topic\s+is\s+(.+)$/i);
const topic = topicMatch ? topicMatch[1].trim() : 'Meeting';

const now = new Date();
const day = now.getDay();
const daysUntilNextMonday = ((8 - day) % 7) || 7;
const nextMonday = new Date(now);
nextMonday.setDate(now.getDate() + daysUntilNextMonday);
nextMonday.setHours(0,0,0,0);

const weekStart = new Date(nextMonday);
const weekEnd = new Date(nextMonday);
weekEnd.setDate(weekEnd.getDate() + 7);

const summary = `${durationMinutes/60}hr call: ${topic}`;
const agenda = [
  `Topic: ${topic}`,
  '1) Quick introductions and context',
  '2) Demo walk-through and key workflows',
  '3) Q&A and next steps'
].join('\n');

return [{
  json: {
    originalRequest: text,
    attendees,
    attendeesCsv: attendees.join(', '),
    durationMinutes,
    avoidBeforeHour,
    topic,
    summary,
    agenda,
    windowStart: weekStart.toISOString(),
    windowEnd: weekEnd.toISOString()
  }
}];

const req = $('Parse Request').first().json;

const busy = items
  .map(i => i.json)
  .filter(e => e && e.start && e.end)
  .map(e => ({
    start: new Date(e.start.dateTime || e.start),
    end: new Date(e.end.dateTime || e.end),
  }))
  .filter(e => !isNaN(e.start) && !isNaN(e.end))
  .sort((a,b) => a.start - b.start);

const durationMs = req.durationMinutes * 60 * 1000;
const windowStart = new Date(req.windowStart);
const windowEnd = new Date(req.windowEnd);

let candidate = new Date(windowStart);
if (candidate.getHours() < req.avoidBeforeHour) {
  candidate.setHours(req.avoidBeforeHour, 0, 0, 0);
}
if (candidate.getHours() >= 17) {
  candidate.setDate(candidate.getDate() + 1);
  candidate.setHours(req.avoidBeforeHour, 0, 0, 0);
}

function isWeekend(d) {
  const day = d.getDay();
  return day === 0 || day === 6;
}

function normalizeCandidate(d, avoidBeforeHour) {
  const x = new Date(d);
  while (isWeekend(x)) {
    x.setDate(x.getDate() + 1);
    x.setHours(avoidBeforeHour, 0, 0, 0);
  }
  if (x.getHours() < avoidBeforeHour) x.setHours(avoidBeforeHour, 0, 0, 0);
  if (x.getHours() >= 17) {
    x.setDate(x.getDate() + 1);
    x.setHours(avoidBeforeHour, 0, 0, 0);
    return normalizeCandidate(x, avoidBeforeHour);
  }
  return x;
}

candidate = normalizeCandidate(candidate, req.avoidBeforeHour);
let chosenStart = null;
let chosenEnd = null;

while (candidate < windowEnd) {
  const end = new Date(candidate.getTime() + durationMs);
  if (end.getHours() > 17 || (end.getHours() === 17 && end.getMinutes() > 0)) {
    candidate.setDate(candidate.getDate() + 1);
    candidate.setHours(req.avoidBeforeHour, 0, 0, 0);
    candidate = normalizeCandidate(candidate, req.avoidBeforeHour);
    continue;
  }

  const overlaps = busy.some(b => candidate < b.end && end > b.start);
  if (!overlaps) {
    chosenStart = new Date(candidate);
    chosenEnd = new Date(end);
    break;
  }

  candidate = new Date(candidate.getTime() + 30 * 60 * 1000);
  candidate = normalizeCandidate(candidate, req.avoidBeforeHour);
}

if (!chosenStart || !chosenEnd) {
  throw new Error('No slot found in requested window.');
}

return [{
  json: {
    ...req,
    bestStart: chosenStart.toISOString(),
    bestEnd: chosenEnd.toISOString(),
    invitationText: `Hi,\n\nYou are invited to: ${req.summary}\nWhen: ${chosenStart.toISOString()} to ${chosenEnd.toISOString()}\n\nAgenda:\n${req.agenda}\n\nBest,\nScheduler Bot`
  }
}];

